  "cat.plan.nav": "Planificar",
  "cat.plan.title": "Planifica tu día",
  "cat.plan.sub": "Apunta por la mañana las tareas del día. Dayloom las reparte en tu horario laboral según la carga, respetando las reuniones y la pausa para comer.",
  "f2.lock.t": "Un plan que fijas",
  "f2.lock.d": "Pulsa “Empezar mi día” y el plan queda fijado. Así avanzas en él en lugar de reorganizarlo.",
  "f2.meet.t": "Las reuniones, en tu plan",
  "f2.meet.d": "Las reuniones del calendario de tu Mac se convierten en bloques fijos y las tareas se programan a su alrededor. Después, puedes añadir tareas de seguimiento al momento.",
  "f2.capture.t": "Captura rápida desde cualquier lugar",
  "f2.capture.d": "Pulsa ⌃⌥D en cualquier app y escribe “tarea @persona #proyecto !carga”. Va directa a tu bandeja de entrada.",
  "f2.detail.t": "Todo sobre una tarea en un solo lugar",
  "f2.detail.d": "Edita los detalles, cambia el día y adjunta y previsualiza archivos sin salir de Dayloom.",
  "f2.review.t": "Resumen del final del día",
  "f2.review.d": "Mira lo que has terminado y pasa lo pendiente a mañana con un clic.",
  "f2.calendar.t": "Planifica con antelación",
  "f2.calendar.d": "Planifica los próximos días en el calendario, haz que las tareas se repitan y marca tus días libres para no romper tu racha.",
  "cat.req.nav": "Peticiones",
  "cat.req.title": "Peticiones de tus herramientas",
  "cat.req.sub": "Las peticiones que llegan a Apple Mail, GitHub, Jira y Linear aparecen como sugerencias en tu bandeja de entrada. Tú decides cuáles se convierten en tareas.",
  "f2.inbox.t": "Una sola bandeja de entrada para todas las peticiones",
  "f2.inbox.d": "Cada sugerencia muestra el remitente, una nota breve y la fecha límite, si la hay. Añádela a tu bandeja de entrada o descártala.",
  "f2.sources.t": "Apple Mail, GitHub, Jira y Linear",
  "f2.sources.d": "Las conexiones son opcionales y de solo lectura. Las claves se guardan en el llavero de tu Mac.",
  "f2.smart.t": "Detección inteligente de peticiones",
  "f2.smart.d": "Claude lee los mensajes nuevos y sugiere solo peticiones de trabajo reales, con un título claro y fecha límite.",
  "f2.summary.t": "Correo del final del día",
  "f2.summary.d": "Si quieres, Dayloom prepara un correo con lo que has hecho, lo que pasa a mañana y el tiempo registrado.",
  "cat.ai.nav": "IA",
  "cat.ai.title": "IA y Claude Code",
  "cat.ai.sub": "Convierte notas sueltas en un plan y deja que Claude Code se ocupe de las tareas de software. Tú mantienes el control en cada paso.",
  "f2.ai.t": "Planificar con IA",
  "f2.ai.d": "Escribe lo que tienes en mente o añade PDF, hojas de cálculo, documentos, mapas mentales y capturas de pantalla. Claude los convierte en tareas.",
  "f2.approve.t": "Tú apruebas cada tarea",
  "f2.approve.d": "Se te sugieren fechas, cargas, horas fijas y repeticiones. No se crea nada hasta que lo revisas.",
  "f2.claude.t": "Claude Code resuelve tareas de software",
  "f2.claude.d": "Trabaja en una rama aparte, ejecuta tus pruebas y abre una pull request para que la revises.",
  "f2.auto.t": "Automático, con tu permiso",
  "f2.auto.d": "Las tareas asignadas pueden resolverse automáticamente. Dayloom te pregunta antes de la primera ejecución y trabaja en una tarea cada vez.",
  "f2.prompts.t": "Un prompt de Claude listo para cada tarea",
  "f2.prompts.d": "Con un clic se prepara un prompt claro para cada tarea, listo para copiar en Claude.",
  "f2.dev.t": "Tu trabajo con código también cuenta",
  "f2.dev.d": "Vincula una carpeta de código a un proyecto. Los push y las sesiones de Claude Code se suman a la tarea activa y dan XP.",
  "cat.time.nav": "Tiempo",
  "cat.time.title": "Registro de tiempo",
  "cat.time.sub": "Descubre a dónde va tu horario laboral, sin llevar una hoja de cálculo.",
  "f2.timer.t": "Temporizadores con un clic",
  "f2.timer.d": "Registra un proyecto, una tarea o cualquier otro trabajo. Si se te olvida, añade el tiempo después.",
  "f2.breaks.t": "Pausas y registros ordenados",
  "f2.breaks.d": "Los registros nunca se solapan, y los huecos entre ellos aparecen como pausas.",
  "f2.done.t": "Terminada al detener",
  "f2.done.d": "Cuando detienes el temporizador de una tarea, Dayloom te pregunta si la has terminado.",
  "f2.idle.t": "Detección de inactividad y sugerencias",
  "f2.idle.d": "Dayloom puede preguntarte por el tiempo que estuviste lejos del Mac y sugerirte un temporizador si olvidas iniciarlo. Ambas opciones vienen desactivadas.",
  "f2.totals.t": "Totales diarios, semanales y mensuales",
  "f2.totals.d": "El tiempo en vivo y el manual se muestran por separado, para que las cifras sean fieles.",
  "cat.team.nav": "Equipos",
  "cat.team.title": "Equipos",
  "cat.team.sub": "Los responsables asignan trabajo y ven cómo va el día. Cada persona sigue planificando su propio día.",
  "f2.board.t": "Tablero del equipo",
  "f2.board.d": "El día de todos, uno junto a otro: quién ha empezado, en qué está cada uno y qué va con retraso.",
  "f2.assign.t": "Asigna con archivos y repeticiones",
  "f2.assign.d": "Asigna una tarea a varias personas a la vez, adjunta archivos y repítela los días laborables que elijas.",
  "f2.sendback.t": "Devuelve trabajo con una nota",
  "f2.sendback.d": "Devuelve una tarea terminada con una nota. Vuelve al principio de la lista de esa persona o al día que elijas.",
  "f2.members.t": "Códigos de invitación y roles",
  "f2.members.d": "Invita a personas con un código y asígnales un rol: admin, responsable o miembro. Únete a varios equipos y cambia entre ellos.",
  "f2.reports.t": "Informes de tiempo y trabajo",
  "f2.reports.d": "Por persona, proyecto y día, para un día, una semana, un mes o cualquier periodo. Exporta a CSV con un clic.",
  "f2.projects.t": "Proyectos y clientes",
  "f2.projects.d": "Hitos, archivos y novedades para cada proyecto. Las finanzas solo las ven los admins y los responsables.",
  "cat.mac.nav": "Mac",
