  "f2.calendar.d": "Rencanakan hari-hari berikutnya di kalender, atur tugas berulang, dan tandai hari libur agar hari beruntun Anda tidak terputus.",
  "cat.req.nav": "Permintaan",
  "cat.req.title": "Permintaan dari alat Anda",
  "cat.req.sub": "Permintaan yang masuk lewat Apple Mail, GitHub, Jira, dan Linear muncul di Kotak Masuk sebagai saran. Anda yang memutuskan mana yang menjadi tugas.",
  "f2.inbox.t": "Satu Kotak Masuk untuk semua permintaan",
  "f2.inbox.d": "Setiap saran menampilkan pengirim, catatan singkat, dan tenggat jika ada. Tambahkan ke Kotak Masuk atau abaikan.",
  "f2.sources.t": "Apple Mail, GitHub, Jira, dan Linear",
  "f2.sources.d": "Sambungan bersifat opsional dan hanya-baca. Kunci disimpan di Rantai Kunci Mac Anda.",
  "f2.smart.t": "Deteksi cerdas permintaan",
  "f2.smart.d": "Claude membaca pesan baru dan hanya menyarankan permintaan kerja yang nyata, dengan judul yang jelas dan tenggat.",
  "f2.summary.t": "Email akhir hari",
  "f2.summary.d": "Jika Anda mau, Dayloom menyiapkan email berisi apa yang sudah Anda kerjakan, apa yang pindah ke besok, dan waktu yang tercatat.",
  "cat.ai.nav": "AI",
  "cat.ai.title": "AI dan Claude Code",
  "cat.ai.sub": "Ubah catatan kasar menjadi rencana, dan serahkan tugas perangkat lunak kepada Claude Code. Anda tetap memegang kendali di setiap langkah.",
  "f2.ai.t": "Rencanakan dengan AI",
  "f2.ai.d": "Tulis apa yang ada di pikiran Anda, atau tambahkan PDF, spreadsheet, dokumen, peta pikiran, dan tangkapan layar. Claude mengubahnya menjadi tugas.",
  "f2.approve.t": "Anda menyetujui setiap tugas",
  "f2.approve.d": "Tanggal, beban kerja, waktu tetap, dan pengulangan disarankan untuk Anda. Tidak ada yang dibuat sebelum Anda meninjaunya.",
  "f2.claude.t": "Claude Code menyelesaikan tugas perangkat lunak",
  "f2.claude.d": "Claude Code bekerja di branch terpisah, menjalankan tes Anda, dan membuka pull request untuk ditinjau.",
  "f2.auto.t": "Otomatis, dengan persetujuan Anda",
  "f2.auto.d": "Tugas yang ditugaskan dapat diselesaikan secara otomatis. Dayloom meminta izin sebelum proses pertama dan mengerjakan satu tugas dalam satu waktu.",
  "f2.prompts.t": "Prompt Claude siap pakai untuk setiap tugas",
  "f2.prompts.d": "Satu klik menyiapkan prompt yang jelas untuk setiap tugas, siap disalin ke Claude.",
  "f2.dev.t": "Pekerjaan kode Anda ikut terhitung",
  "f2.dev.d": "Hubungkan folder kode ke sebuah proyek. Push dan sesi Claude Code ditambahkan ke tugas yang aktif dan menghasilkan XP.",
  "cat.time.nav": "Waktu",
  "cat.time.title": "Pelacakan waktu",
  "cat.time.sub": "Lihat ke mana jam kerja Anda pergi, tanpa perlu mengisi spreadsheet.",
  "f2.timer.t": "Timer sekali klik",
  "f2.timer.d": "Lacak proyek, tugas, atau pekerjaan lainnya. Jika lupa, tambahkan waktunya belakangan.",
  "f2.breaks.t": "Istirahat dan entri yang rapi",
  "f2.breaks.d": "Entri tidak pernah tumpang tindih, dan jeda di antaranya ditampilkan sebagai istirahat.",
  "f2.done.t": "Selesai saat Anda berhenti",
  "f2.done.d": "Saat Anda menghentikan timer sebuah tugas, Dayloom menanyakan apakah tugas itu sudah selesai.",
  "f2.idle.t": "Deteksi tidak aktif dan saran",
  "f2.idle.d": "Dayloom dapat menanyakan waktu saat Anda jauh dari Mac dan menyarankan timer saat Anda lupa memulainya. Keduanya nonaktif secara default.",
  "f2.totals.t": "Total harian, mingguan, dan bulanan",
  "f2.totals.d": "Waktu langsung dan waktu manual ditampilkan terpisah, sehingga angkanya tetap jujur.",
  "cat.team.nav": "Tim",
  "cat.team.title": "Tim",
  "cat.team.sub": "Manajer membagikan pekerjaan dan melihat perkembangan hari itu. Setiap orang tetap merencanakan harinya sendiri.",
  "f2.board.t": "Papan tim",
  "f2.board.d": "Hari setiap orang berdampingan: siapa yang sudah mulai, apa yang sedang dikerjakan, dan apa yang terlambat.",
  "f2.assign.t": "Bagikan tugas dengan file dan pengulangan",
  "f2.assign.d": "Bagikan tugas ke beberapa orang sekaligus, lampirkan file, dan ulangi pada hari kerja yang Anda pilih.",
  "f2.sendback.t": "Kembalikan pekerjaan dengan catatan",
  "f2.sendback.d": "Kembalikan tugas yang sudah selesai dengan catatan. Tugas kembali ke urutan teratas daftar orang tersebut atau ke hari yang Anda pilih.",
  "f2.members.t": "Kode undangan dan peran",
  "f2.members.d": "Undang orang dengan kode dan beri mereka peran: admin, manajer, atau anggota. Bergabunglah dengan beberapa tim dan beralih di antaranya.",
  "f2.reports.t": "Laporan waktu dan pekerjaan",
  "f2.reports.d": "Per orang, proyek, dan hari, untuk satu hari, minggu, bulan, atau rentang apa pun. Ekspor ke CSV dengan satu klik.",
  "f2.projects.t": "Proyek dan klien",
  "f2.projects.d": "Tonggak, file, dan pembaruan untuk setiap proyek. Data keuangan hanya terlihat oleh admin dan manajer.",
  "cat.mac.nav": "Mac",
  "cat.mac.title": "Selalu terlihat",
  "cat.mac.sub": "Dayloom adalah aplikasi Mac native. Tugas Anda saat ini selalu terlihat sekilas.",
  "f2.menubar.t": "Bar menu",
  "f2.menubar.d": "Tugas Anda saat ini dan sisa hari Anda, satu klik saja, lengkap dengan catat cepat dan timer.",
  "f2.panel.t": "Panel mengambang",
  "f2.panel.d": "Panel kecil di setiap desktop menampilkan apa yang sedang dan akan dikerjakan. Seret ke mana pun Anda mau.",
  "f2.widgets.t": "Widget",
  "f2.widgets.d": "Widget kecil, sedang, dan besar untuk desktop dan Pusat Notifikasi Anda.",
  "f2.shortcuts.t": "Pintasan, Siri, dan Spotlight",
  "f2.shortcuts.d": "Tambahkan tugas, mulai atau hentikan timer, tanyakan apa yang berikutnya, dan temukan tugas yang belum selesai di Spotlight.",
  "f2.safari.t": "Ekstensi Safari",
  "f2.safari.d": "Kirim halaman yang sedang Anda buka, atau teks yang Anda pilih, ke Dayloom sebagai tugas. Chrome, Edge, dan Brave segera hadir.",
  "f2.theme.t": "Terang dan gelap",
  "f2.theme.d": "Mengikuti tampilan sistem Anda, atau pilih sendiri terang atau gelap.",
  "f2.tour.t": "Awal yang terpandu",
  "f2.tour.d": "Pengenalan singkat dan tur opsional membantu Anda mengenal aplikasi. Anda dapat membuka tur lagi dari menu Bantuan.",
  "cat.mot.nav": "Motivasi",
  "cat.mot.title": "Motivasi dan berbagi",
  "cat.mot.sub": "Pekerjaan yang selesai dihargai dengan tenang, dan Anda dapat membagikan kemajuan Anda jika mau.",
  "f2.levels.t": "Level, hari beruntun, dan lencana",
  "f2.levels.d": "Pekerjaan yang selesai tepat waktu menghasilkan XP dan lebih dari 200 lencana. Hari libur tidak memutus hari beruntun Anda.",
  "f2.cards.t": "Bagikan hari Anda",
  "f2.cards.d": "Bagikan hari yang sudah selesai sebagai kartu gambar yang rapi. Nama tugas, proyek, dan klien tidak pernah disertakan.",
  "f2.week.t": "Rangkuman mingguan",
  "f2.week.d": "Ringkasan minggu Anda, hari demi hari, siap dibagikan.",
  "f2.badge.t": "Lencana dan level",
  "f2.badge.d": "Setiap lencana, level, atau hari beruntun baru dapat dibagikan dengan kartunya sendiri.",
  "f2.lb.t": "Papan peringkat publik",
  "f2.lb.d": "Opsional. Tampilkan level dan XP Anda di papan peringkat publik, tanpa pernah menampilkan judul tugas.",
  "f2.profile.t": "Profil Anda",
  "f2.profile.d": "Pilih nama pengguna dan tambahkan akun media sosial Anda ke kartu yang Anda bagikan.",
  "cat.priv.nav": "Privasi",
  "cat.priv.title": "Privat dan andal",
  "cat.priv.sub": "Dayloom menyimpan data Anda di Mac Anda dan tidak mengganggu pekerjaan Anda.",
  "p2.local.t": "Data Anda tetap di Mac Anda",
  "p2.local.d": "Rencana pribadi, entri waktu, dan file disimpan di Mac Anda. Fitur tim bersifat opsional.",
  "p2.read.t": "Sambungan hanya-baca",
  "p2.read.d": "Sambungan hanya membaca apa yang dicantumkan. Teks pesan dikirim ke AI hanya dengan Deteksi cerdas, dan hanya jika Anda mengaktifkannya.",
  "p2.backup.t": "Cadangan harian",
  "p2.backup.d": "30 hari terakhir dicadangkan secara otomatis. Ekspor, pemulihan, dan CSV sudah tersedia.",
  "p2.account.t": "Tanpa perlu akun",
  "p2.account.d": "Gunakan Dayloom tanpa masuk akun. Buat akun hanya saat Anda membutuhkan Pro atau tim.",
  "p2.updates.t": "Dinotarisasi, diperbarui otomatis",
  "p2.updates.d": "Ditandatangani dan dinotarisasi oleh Apple. Versi baru terpasang di latar belakang.",
  "p2.lang.t": "16 bahasa",
  "p2.lang.d": "Dayloom, situs web ini, dan kartu berbagi tersedia dalam 16 bahasa.",
