  "f2.detail.t": "任务信息集中一处",
  "f2.detail.d": "无需离开 Dayloom，即可编辑详情、更改日期，以及添加和预览文件。",
  "f2.review.t": "每日回顾",
  "f2.review.d": "查看已完成的工作，一键把剩余任务移到明天。",
  "f2.calendar.t": "提前规划",
  "f2.calendar.d": "在日历中规划未来的日子，设置重复任务，并标记休息日，连续纪录不会因此中断。",
  "cat.req.nav": "请求",
  "cat.req.title": "来自各类工具的请求",
  "cat.req.sub": "来自 Apple Mail、GitHub、Jira 和 Linear 的请求会作为建议显示在收件箱中。由你决定哪些成为任务。",
  "f2.inbox.t": "一个收件箱，汇集所有请求",
  "f2.inbox.d": "每条建议都会显示发件人、简短说明以及截止日期（如有）。可以添加到收件箱，也可以忽略。",
  "f2.sources.t": "Apple Mail、GitHub、Jira 和 Linear",
  "f2.sources.d": "连接均为可选，且仅为只读。密钥保存在你 Mac 的钥匙串中。",
  "f2.smart.t": "智能识别请求",
  "f2.smart.d": "Claude 会阅读新消息，只推荐真正的工作请求，并附上清晰的标题和截止日期。",
  "f2.summary.t": "每日总结邮件",
  "f2.summary.d": "如有需要，Dayloom 会准备一封邮件，列出你完成的工作、移到明天的任务以及记录的时间。",
  "cat.ai.nav": "AI",
  "cat.ai.title": "AI 与 Claude Code",
  "cat.ai.sub": "把零散的笔记变成计划，把软件任务交给 Claude Code。每一步都由你掌控。",
  "f2.ai.t": "用 AI 规划",
  "f2.ai.d": "写下你的想法，或添加 PDF、电子表格、文档、思维导图和截图。Claude 会把它们转为任务。",
  "f2.approve.t": "每个任务都由你批准",
  "f2.approve.d": "日期、工作量、固定时间和重复规则都会给出建议。在你审核之前，不会创建任何任务。",
  "f2.claude.t": "Claude Code 解决软件任务",
  "f2.claude.d": "Claude Code 在独立分支上工作，运行你的测试，并创建 pull request 供你审查。",
  "f2.auto.t": "经你同意后自动处理",
  "f2.auto.d": "分配给你的任务可以自动解决。Dayloom 会在首次运行前征求你的同意，并且一次只处理一个任务。",
  "f2.prompts.t": "每个任务都有现成的 Claude 提示词",
  "f2.prompts.d": "一键即可为任意任务生成清晰的提示词，可直接复制到 Claude。",
  "f2.dev.t": "代码工作也算在内",
  "f2.dev.d": "把代码文件夹关联到项目。推送和 Claude Code 会话会计入当前任务，并获得 XP。",
  "cat.time.nav": "时间",
  "cat.time.title": "时间追踪",
  "cat.time.sub": "无需维护表格，也能看清工作时间花在了哪里。",
  "f2.timer.t": "一键计时",
  "f2.timer.d": "为项目、任务或其他工作计时。忘记计时的话，可以事后补录。",
  "f2.breaks.t": "休息与整洁的记录",
  "f2.breaks.d": "记录之间永不重叠，中间的空档会显示为休息。",
  "f2.done.t": "停止时确认完成",
  "f2.done.d": "停止某个任务的计时后，Dayloom 会询问该任务是否已完成。",
  "f2.idle.t": "空闲检测与计时建议",
  "f2.idle.d": "Dayloom 可以询问你离开 Mac 的时间，并在你忘记计时时提出建议。两项功能默认均为关闭。",
  "f2.totals.t": "每日、每周和每月合计",
  "f2.totals.d": "实时计时与手动记录分开显示，数字真实可信。",
  "cat.team.nav": "团队",
  "cat.team.title": "团队",
  "cat.team.sub": "管理者分配工作，随时了解当天进展。每个人仍然规划自己的一天。",
  "f2.board.t": "团队看板",
  "f2.board.d": "每个人的一天并排呈现：谁已开始、正在做什么、哪些工作已延误。",
  "f2.assign.t": "分配任务，支持附件和重复",
  "f2.assign.d": "一次将任务分配给多人，附上文件，并在你选择的工作日重复。",
  "f2.sendback.t": "附上备注退回工作",
  "f2.sendback.d": "附上备注退回已完成的任务。任务会回到对方列表的顶部，或回到你选择的日期。",
  "f2.members.t": "邀请码与角色",
  "f2.members.d": "用邀请码邀请成员，并分配角色：管理员、经理或成员。可以加入多个团队并随时切换。",
  "f2.reports.t": "时间与工作报告",
  "f2.reports.d": "按人员、项目和日期统计，可查看一天、一周、一个月或任意时间段。一键导出为 CSV。",
  "f2.projects.t": "项目与客户",
  "f2.projects.d": "每个项目都有里程碑、文件和动态。财务信息仅管理员和经理可见。",
  "cat.mac.nav": "Mac",
  "cat.mac.title": "始终可见",
  "cat.mac.sub": "Dayloom 是原生 Mac App。当前任务一眼就能看到。",
  "f2.menubar.t": "菜单栏",
  "f2.menubar.d": "当前任务和当天剩余安排一键可达，还可快速记录和计时。",
  "f2.panel.t": "浮动面板",
  "f2.panel.d": "每个桌面上的小面板显示当前和下一项任务。可以拖到任意位置。",
  "f2.widgets.t": "小组件",
  "f2.widgets.d": "适用于桌面和通知中心的小、中、大尺寸小组件。",
  "f2.shortcuts.t": "快捷指令、Siri 和 Spotlight",
  "f2.shortcuts.d": "添加任务、开始或停止计时、询问下一步做什么，并在 Spotlight 中查找未完成的任务。",
  "f2.safari.t": "Safari 扩展",
  "f2.safari.d": "将当前网页或所选文字作为任务发送到 Dayloom。Chrome、Edge 和 Brave 版本即将推出。",
  "f2.theme.t": "浅色与深色",
  "f2.theme.d": "跟随系统外观，也可以自行选择浅色或深色。",
  "f2.tour.t": "引导式上手",
  "f2.tour.d": "简短的介绍和可选的导览帮助你熟悉 App。可随时从“帮助”菜单重新打开导览。",
  "cat.mot.nav": "激励",
  "cat.mot.title": "激励与分享",
  "cat.mot.sub": "完成的工作会得到低调的认可，你也可以按需分享自己的进展。",
  "f2.levels.t": "等级、连续纪录和徽章",
  "f2.levels.d": "按时完成工作可获得 XP 和 200 多枚徽章。休息日不会中断连续纪录。",
  "f2.cards.t": "分享你的一天",
  "f2.cards.d": "以简洁的图片卡片分享已完成的一天。任务、项目和客户名称始终不会显示。",
  "f2.week.t": "每周回顾",
  "f2.week.d": "逐日汇总你的一周，可直接分享。",
  "f2.badge.t": "徽章与等级",
  "f2.badge.d": "每枚新徽章、每次升级或新的连续纪录，都可以用专属卡片分享。",
  "f2.lb.t": "公开排行榜",
  "f2.lb.d": "可选。在公开排行榜上显示你的等级和 XP，任务标题始终不会公开。",
  "f2.profile.t": "你的个人资料",
  "f2.profile.d": "选择用户名，并在分享的卡片中添加你的社交账号。",
  "cat.priv.nav": "隐私",
  "cat.priv.title": "私密可靠",
  "cat.priv.sub": "Dayloom 将数据保存在你的 Mac 上，不打扰你的工作。",
  "p2.local.t": "数据保留在你的 Mac 上",
  "p2.local.d": "个人计划、时间记录和文件都存储在你的 Mac 上。团队功能为可选。",
  "p2.read.t": "只读连接",
  "p2.read.d": "连接只读取其列出的内容。只有在使用智能识别且由你开启时，消息文本才会发送给 AI。",
  "p2.backup.t": "每日备份",
  "p2.backup.d": "自动备份最近 30 天的数据。内置导出、恢复和 CSV 功能。",
  "p2.account.t": "无需账户",
  "p2.account.d": "无需登录即可使用 Dayloom。只有需要 Pro 或团队功能时才需创建账户。",
  "p2.updates.t": "经过公证，自动更新",
  "p2.updates.d": "由 Apple 签名并公证。新版本在后台安装。",
  "p2.lang.t": "16 种语言",
  "p2.lang.d": "Dayloom、本网站和分享卡片均支持 16 种语言。",
  "alt.home": "Dayloom 主页，显示今天的计划、时间追踪、等级和收件箱",
  "alt.panel": "显示当前任务和正在运行的计时器的浮动面板",
  "alt.today": "“今天”页面，显示已锁定的计划和“现在”卡片",
