  "sc.kicker": "Dayloom의 모든 기능",
  "sc.title": "하루 업무를 위한 하나의 앱",
  "sc.sub": "기능을 선택하면 앱에서 어떻게 보이는지 확인할 수 있습니다. 모든 스크린샷은 샘플 데이터를 사용한 실제 Dayloom 화면입니다.",
  "sc.legend.free": "모든 사용자에게 포함",
