  "f2.tour.d": "একটি ছোট পরিচিতি আর একটি ঐচ্ছিক ট্যুর আপনাকে অ্যাপটি ঘুরিয়ে দেখায়। সহায়তা মেনু থেকে ট্যুরটি আবার খুলতে পারেন।",
  "cat.mot.nav": "অনুপ্রেরণা",
  "cat.mot.title": "অনুপ্রেরণা ও শেয়ার",
  "cat.mot.sub": "শেষ হওয়া কাজ নিঃশব্দে স্বীকৃতি পায়, আর চাইলে আপনি নিজের অগ্রগতি শেয়ার করতে পারেন।",
  "f2.levels.t": "লেভেল, স্ট্রিক ও ব্যাজ",
  "f2.levels.d": "সময়মতো শেষ হওয়া কাজে মেলে XP আর ২০০টিরও বেশি ব্যাজ। ছুটির দিনে আপনার স্ট্রিক ভাঙে না।",
  "f2.cards.t": "আপনার দিন শেয়ার করুন",
  "f2.cards.d": "শেষ হওয়া একটি দিন পরিচ্ছন্ন ছবির কার্ড হিসেবে শেয়ার করুন। কাজ, প্রজেক্ট ও ক্লায়েন্টের নাম কখনো থাকে না।",
  "f2.week.t": "সাপ্তাহিক সারসংক্ষেপ",
  "f2.week.d": "আপনার সপ্তাহের দিনভিত্তিক সারসংক্ষেপ, শেয়ার করার জন্য প্রস্তুত।",
  "f2.badge.t": "ব্যাজ ও লেভেল",
  "f2.badge.d": "প্রতিটি নতুন ব্যাজ, লেভেল বা স্ট্রিক নিজস্ব কার্ডে শেয়ার করা যায়।",
  "f2.lb.t": "পাবলিক লিডারবোর্ড",
  "f2.lb.d": "ঐচ্ছিক। পাবলিক লিডারবোর্ডে আপনার লেভেল ও XP দেখান, আপনার কাজের শিরোনাম কখনো নয়।",
  "f2.profile.t": "আপনার প্রোফাইল",
  "f2.profile.d": "একটি ইউজারনেম বেছে নিন এবং শেয়ার করা কার্ডে আপনার সোশ্যাল অ্যাকাউন্ট যোগ করুন।",
  "cat.priv.nav": "গোপনীয়তা",
  "cat.priv.title": "গোপন ও নির্ভরযোগ্য",
  "cat.priv.sub": "Dayloom আপনার ডেটা আপনার Mac-এ রাখে এবং আপনার কাজে বাধা দেয় না।",
  "p2.local.t": "আপনার ডেটা আপনার Mac-এ থাকে",
  "p2.local.d": "ব্যক্তিগত পরিকল্পনা, সময়ের এন্ট্রি ও ফাইল আপনার Mac-এ সংরক্ষিত থাকে। টিম ফিচার ঐচ্ছিক।",
  "p2.read.t": "শুধু পড়ার সংযোগ",
  "p2.read.d": "সংযোগগুলো শুধু তালিকায় থাকা তথ্যই পড়ে। বার্তার লেখা AI-তে পাঠানো হয় শুধু স্মার্ট শনাক্তকরণের মাধ্যমে, এবং তা-ও কেবল আপনি চালু করলে।",
  "p2.backup.t": "দৈনিক ব্যাকআপ",
  "p2.backup.d": "শেষ ৩০ দিনের ব্যাকআপ স্বয়ংক্রিয়ভাবে নেওয়া হয়। এক্সপোর্ট, রিস্টোর ও CSV আগে থেকেই আছে।",
  "p2.account.t": "অ্যাকাউন্টের দরকার নেই",
  "p2.account.d": "সাইন ইন না করেই Dayloom ব্যবহার করুন। শুধু Pro বা টিমের দরকার হলে অ্যাকাউন্ট তৈরি করুন।",
  "p2.updates.t": "নোটারাইজড, স্বয়ংক্রিয় আপডেট",
  "p2.updates.d": "Apple দ্বারা স্বাক্ষরিত ও নোটারাইজড। নতুন সংস্করণ ব্যাকগ্রাউন্ডে ইনস্টল হয়।",
  "p2.lang.t": "১৬টি ভাষা",
