  "f2.inbox.t": "Một Hộp thư đến cho mọi yêu cầu",
  "f2.inbox.d": "Mỗi gợi ý hiển thị người gửi, một ghi chú ngắn và hạn chót nếu có. Thêm vào Hộp thư đến hoặc bỏ qua.",
  "f2.sources.t": "Apple Mail, GitHub, Jira và Linear",
  "f2.sources.d": "Các kết nối là tùy chọn và chỉ đọc. Khóa được lưu trong Chuỗi khóa trên Mac của bạn.",
  "f2.smart.t": "Nhận diện yêu cầu thông minh",
