  "f2.summary.t": "Email cuối ngày",
  "f2.summary.d": "Nếu bạn muốn, Dayloom soạn một email gồm những việc bạn đã làm, những việc chuyển sang ngày mai và thời gian đã ghi.",
  "cat.ai.nav": "AI",
  "cat.ai.title": "AI và Claude Code",
